import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            int k = sc.nextInt();
            double[] p = new double[n];
            for (int i = 0; i < n; i++) {
                p[i] = sc.nextDouble();
            }

            int size = 1 << n;
            double[] sum_mask = new double[size];
            Arrays.fill(sum_mask, 0.0);
            for (int mask = 0; mask < size; mask++) {
                for (int j = 0; j < n; j++) {
                    if ((mask & (1 << j)) != 0) {
                        sum_mask[mask] += p[j];
                    }
                }
            }

            int active = 0;
            for (double prob : p) {
                if (prob > 1e-5) active++;
            }

            if (active <= k) {
                for (int i = 0; i < n; i++) {
                    double val = (p[i] > 1e-5) ? 1.0 : 0.0;
                    System.out.print(val);
                    if (i + 1 != n) System.out.print(" ");
                }
                System.out.println();
                continue;
            }

            double[] dp = new double[size];
            Arrays.fill(dp, 0.0);
            dp[0] = 1.0;

            for (int mask = 0; mask < size; mask++) {
                int remaining = (~mask) & (size - 1);
                for (int i = 0; i < n; i++) {
                    if (((remaining & (1 << i)) != 0) && p[i] > 1e-5) {
                        dp[mask | (1 << i)] += dp[mask] * p[i] / sum_mask[remaining];
                    }
                }
            }

            double[] answer = new double[n];
            Arrays.fill(answer, 0.0);
            for (int mask = 0; mask < size; mask++) {
                int count_bits = Integer.bitCount(mask);
                if (count_bits != k) continue;
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) != 0) {
                        answer[i] += dp[mask];
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                System.out.print(answer[i]);
                if (i + 1 != n) System.out.print(" ");
            }
            System.out.println();
        }
        sc.close();
    }
}
